-- V1
create table if not exists cliente (fecha_registro date, id integer, codigo varchar(10) not null unique, tipo varchar(10) not null check (tipo in ('PERSONA','EMPRESA')), documento varchar(11), ciudad varchar(255), direccion varchar(255), email varchar(255), nombre varchar(255) not null, telefono varchar(255), primary key (id));
create table if not exists consumo_real (estimado float not null, fecha date, real_consumido float not null, id integer, material_id bigint not null, op_codigo varchar(12) not null, ficha_uid varchar(16), producto varchar(255), responsable varchar(255), primary key (id));
create table if not exists empleado (ingreso date, dni varchar(8), id integer, codigo varchar(10) not null unique, etapa varchar(20) check (etapa in ('PENDIENTE','CORTE_MADERA','ARMADO','CINCHADO','ESPUMADO','CORTE_TELA','COSTURA','TAPIZADO','ACABADO','CONTROL_CALIDAD','LISTO')), rol varchar(20) check (rol in ('GERENTE','ADMINISTRADOR','VENDEDOR','SUPERVISOR','CARPINTERO','COSTURERA','TAPICERO','ALMACENERO')), area varchar(255), cargo varchar(255), color varchar(255), estado varchar(255), nombre varchar(255) not null, telefono varchar(255), primary key (id));
create table if not exists empresa (id bigint not null, ciudad varchar(255), direccion varchar(255), email varchar(255), logo varchar(255), nombre_comercial varchar(255), razon_social varchar(255), ruc varchar(255), telefono varchar(255), web varchar(255), primary key (id));
create table if not exists ficha_hijo (orden integer not null, ficha_id bigint not null, codigo_hijo varchar(10), primary key (orden, ficha_id));
create table if not exists ficha_tecnica (alto integer, chaise boolean, compuesta boolean, cuerpos integer, fecha_aprobacion date, fondo integer, indirectos_pct float, largo integer, version integer not null, id integer, producto_id bigint, codigo varchar(10) not null, estado varchar(10) not null check (estado in ('BORRADOR','APROBADA','OBSOLETA')), uid varchar(16) not null unique, notas varchar(500), aprobado_por varchar(255), nombre varchar(255) not null, tipo_corte varchar(255), primary key (id));
create table if not exists gasto (fecha date, monto numeric(12,2) not null, id integer, categoria varchar(255), concepto varchar(255), primary key (id));
create table if not exists item_compra (cantidad float not null, precio_unitario numeric(12,2) not null, id integer, material_id bigint not null, orden_id bigint not null, tela_id bigint, primary key (id));
create table if not exists item_venta (cantidad integer not null, precio_unitario numeric(12,2) not null, id integer, producto_id bigint not null, venta_id bigint not null, tela_codigo varchar(255), primary key (id));
create table if not exists linea_bom (cantidad float not null, dependencia varchar(4) not null check (dependencia in ('F','L','LF','LA','T','N','P')), merma_pct float not null, opcional boolean not null, orden integer, ficha_id bigint not null, id integer, material_id bigint not null, componente varchar(20) not null check (componente in ('ESTRUCTURA','ASIENTO','RESPALDO','BRAZOS','TAPIZADO','COJINES','ENSAMBLAJE','PATAS','ACABADO','EMBALAJE','MECANISMO')), primary key (id));
create table if not exists material (bajo_pedido boolean not null, costo float not null, minimo float not null, reservado float not null, stock float not null, id integer, proveedor_id bigint, codigo varchar(20) not null unique, unidad varchar(20) not null, categoria varchar(30) not null, nombre varchar(255) not null, ubicacion varchar(255), primary key (id));
create table if not exists movimiento (cantidad float not null, saldo float, fecha timestamp not null, id integer, material_id bigint not null, tipo varchar(20) not null check (tipo in ('ENTRADA','SALIDA','AJUSTE','RESERVA','LIBERACION','CONSUMO_OP','RETAZO')), concepto varchar(255), referencia varchar(255), usuario varchar(255), primary key (id));
create table if not exists notificacion_estado (descartada boolean, leida boolean, clave varchar(80) not null, primary key (clave));
create table if not exists op_extra (cantidad float, op_id bigint not null, componente varchar(20), material_codigo varchar(20));
create table if not exists op_sustitucion (op_id bigint not null, elegido varchar(20), original varchar(20) not null, primary key (op_id, original));
create table if not exists operacion_mo (costo_hora float not null, horas float not null, orden integer, ficha_id bigint not null, id integer, etapa varchar(20) not null check (etapa in ('CORTE','CARPINTERIA','COSTURA','TAPIZADO','ACABADO','CONTROL_CALIDAD')), primary key (id));
create table if not exists orden_compra (fecha date, fecha_entrega date, fecha_pago date, fecha_recepcion date, nueva boolean, id integer, proveedor_id bigint not null, codigo varchar(12) not null unique, estado varchar(12) not null check (estado in ('BORRADOR','SOLICITADA','APROBADA','RECIBIDA','CANCELADA')), observaciones varchar(500), origen varchar(255), primary key (id));
create table if not exists orden_produccion (alto integer, anulada boolean not null, cantidad integer not null, costo numeric(12,2), cuerpos integer, fecha_entrega date, fecha_fin date, fecha_inicio date, fondo integer, largo integer, cliente_id bigint, id integer, producto_id bigint, responsable_id bigint, tela_id bigint, prioridad varchar(10) not null check (prioridad in ('ALTA','MEDIA','BAJA')), codigo varchar(12) not null unique, pedido_codigo varchar(12), retapizado_codigo varchar(12), ficha_uid varchar(16), etapa varchar(20) not null check (etapa in ('PENDIENTE','CORTE_MADERA','ARMADO','CINCHADO','ESPUMADO','CORTE_TELA','COSTURA','TAPIZADO','ACABADO','CONTROL_CALIDAD','LISTO')), autorizacion varchar(300), especificacion varchar(600), nombre_personalizado varchar(255), primary key (id));
create table if not exists pago (fecha date, monto numeric(12,2) not null, cliente_id bigint not null, id integer, referencia varchar(12), concepto varchar(255), metodo varchar(255), primary key (id));
create table if not exists parametro (clave varchar(60) not null, valor varchar(255) not null, primary key (clave));
create table if not exists pedido (adelanto numeric(12,2) not null, alto integer, cantidad integer, fecha date, fecha_entrega date, fondo integer, largo integer, precio numeric(12,2) not null, cliente_id bigint not null, id integer, producto_id bigint, tela_id bigint, codigo varchar(12) not null unique, op_codigo varchar(12), estado varchar(15) not null check (estado in ('REGISTRADO','COTIZADO','CONFIRMADO','EN_PRODUCCION','LISTO','ENTREGADO','CANCELADO')), tipo varchar(15) not null check (tipo in ('ESTANDAR','PERSONALIZADO')), especificacion varchar(600), observaciones varchar(600), configuracion varchar(800), material varchar(255), primary key (id));
create table if not exists permiso (editar boolean, ver boolean, id integer, rol varchar(20) not null check (rol in ('GERENTE','ADMINISTRADOR','VENDEDOR','SUPERVISOR','CARPINTERO','COSTURERA','TAPICERO','ALMACENERO')), modulo varchar(30) not null, primary key (id));
create table if not exists producto (activo boolean not null, alto integer, costo numeric(12,2), cuerpos integer, fondo integer, largo integer, precio numeric(12,2) not null, stock integer not null, id integer, codigo varchar(10) not null unique, forma varchar(20) not null check (forma in ('MODERNO','SECCIONAL_L','SILLON','JUEGO','CHESTERFIELD','SOFA_CAMA','RECLINABLE','ESCANDINAVO','PUFF','SECCIONAL_U')), categoria varchar(30) not null, descripcion varchar(600), imagenes varchar(1500), color varchar(255), color_hex varchar(255), material varchar(255), medidas_texto varchar(255), nombre varchar(255) not null, primary key (id));
create table if not exists proveedor (activo boolean not null, total_comprado numeric(12,2), id integer, codigo varchar(10) not null unique, ruc varchar(11), condicion_pago varchar(255), contacto varchar(255), direccion varchar(255), email varchar(255), razon_social varchar(255) not null, rubro varchar(255), telefono varchar(255), primary key (id));
create table if not exists reclamo_garantia (costo numeric(12,2), fecha date, fecha_cierre date, fecha_compra date, cliente_id bigint not null, id integer, producto_id bigint, codigo varchar(10) not null unique, estado varchar(20) not null check (estado in ('ABIERTO','EN_DIAGNOSTICO','EN_REPARACION','RESUELTO','RECHAZADO')), descripcion varchar(600), diagnostico varchar(600), falla varchar(255) not null, solucion varchar(255), primary key (id));
create table if not exists reserva (cantidad float not null, id integer, material_id bigint not null, op_id bigint not null, primary key (id));
create table if not exists resumen_mensual (anio integer, egresos numeric(12,2), mes integer, sofas integer, ventas numeric(12,2), id integer, primary key (id));
create table if not exists retapizado (alto integer, cuerpos integer, fecha_entrega date, fecha_recojo date, fecha_registro date, fondo integer, largo integer, metros float, total numeric(12,2), cliente_id bigint not null, id integer, tela_id bigint, codigo varchar(10) not null unique, op_codigo varchar(12), estado varchar(20) not null check (estado in ('POR_COTIZAR','COTIZADO','APROBADO','RECOJO_PROGRAMADO','EN_TALLER','LISTO','ENTREGADO')), descripcion varchar(255) not null, espuma varchar(255), estructura varchar(255), foto varchar(255), primary key (id));
create table if not exists tela (descontinuada boolean not null, minimo float not null, stock float not null, id integer, hex varchar(9) not null, codigo varchar(10) not null unique, tipo varchar(20) not null check (tipo in ('CHENILLE','LINO','CUERO','TERCIOPELO','BOUCLE','MICROFIBRA')), codigo_proveedor varchar(255), color varchar(255) not null, primary key (id));
create table if not exists usuario (activo boolean not null, ultimo_acceso date, id integer, rol varchar(20) not null check (rol in ('GERENTE','ADMINISTRADOR','VENDEDOR','SUPERVISOR','CARPINTERO','COSTURERA','TAPICERO','ALMACENERO')), username varchar(40) not null unique, cargo varchar(255), email varchar(255), nombre varchar(255) not null, password_hash varchar(255) not null, primary key (id));
create table if not exists venta (descuento numeric(12,2), numero integer not null, recibido numeric(12,2), serie varchar(4) not null, total numeric(12,2) not null, vuelto numeric(12,2), cliente_id bigint, fecha timestamp not null, id integer, comprobante varchar(10) not null check (comprobante in ('BOLETA','FACTURA')), metodo_pago varchar(255), vendedor varchar(255), primary key (id));
